import {ChangeDetectorRef, Component, HostBinding, OnInit} from '@angular/core';
import {ActivatedRoute, NavigationExtras, Router} from '@angular/router';

import {NavController, Platform} from '@ionic/angular';
import {Plugins} from '@capacitor/core';
import 'ocr';
import {isNotNullOrUndefined} from 'codelyzer/util/isNotNullOrUndefined';
import {ModalService} from 'ng-zorro-antd-mobile';
import {routeAnimation} from '../shared';
import {HttpClientService} from '../shared/http-client.service';
import {environment} from '../../environments/environment';
import {DomSanitizer} from '@angular/platform-browser';

const {Ocr} = Plugins;

@Component({
    selector: 'app-password',
    templateUrl: 'password.page.html',
    styleUrls: ['password.page.scss'],
    animations: [    // 路由动画
        routeAnimation
    ]
})
export class PasswordPage implements OnInit {
   // 信息
    patientInfo = {
        id: '',
        name: undefined,
        identity: undefined,
        mobile: undefined,
        verifyCode: undefined,
        newPassword: undefined
    };
    imageData;
    result: { name: string, sex: string, folk: string, birthday: string, num: string, address: string, imageData: string };
    encodeKey;
    Date: Date;
    verifyCode;
    verifyCodeJpg;
    step = '1';
    constructor(
        private router: Router,
        public navCtrl: NavController,
        private http: HttpClientService,
        private route: ActivatedRoute,
        private ref: ChangeDetectorRef,
        private platform: Platform,
        private deleteModal: ModalService,
        private sanitizer: DomSanitizer
    ) {
        this.platform.backButton.subscribeWithPriority(10, () => {
           this.routeBack();
        });
    }

    @HostBinding('@routeAnimation') state;   // 路由动画
    ngOnInit() {
        this.getVerifyCode();
    }

    ionViewWillEnter() {
    }
    // 清除信息
    clean(){
        this.patientInfo = {
            id: '',
            name: undefined,
            identity: undefined,
            mobile: undefined,
            verifyCode: undefined,
            newPassword: undefined
        };
        this.imageData = '';
        this.step = '1';
    }
    // 路由返回
    routeBack() {
        this.clean();
        this.router.navigate(['/login']);
    }
    checkPhone(phone){
        if (!isNotNullOrUndefined(phone)){
            this.http.showToast('手机号为空，请修改！');
            return false;
        }
        // 通过正则表达式判断手机号码格式是否正确,根据电信，联通、移动手机号码规则可以到以下正则
        // 手机号码第一位是[1]开头，第二位[3-9]中的一位，第三位到第十一位则是[0-9]中的数字；
        // ^1表示开头为1
        // [3|4|5|7|8] 表示3、4、5、7、8中的一位数值
        // [0-9]{9} 匹配包含0-9的数字
        const reg = /^1[3-9][0-9]{9}/;
        if (reg.test(phone) && phone.length === 11){
            return true; // 手机号码正确
        } else {
            this.http.showToast('手机号填写有误，请修改！');
            return false;
        }
    }
    submit() {
        // 判断姓名
        if (!isNotNullOrUndefined(this.patientInfo.name) || this.patientInfo.name === '' || this.patientInfo.name.trim() === ''){
            this.http.showToast('姓名为空，请输入姓名！');
            return;
        }
        // 判断身份证号
        if (!isNotNullOrUndefined(this.patientInfo.identity)){
            this.http.showToast('请扫描身份证！');
            return;
        }
        // 判断手机号
        if (!this.checkPhone(this.patientInfo.mobile)){
            return;
        }
        // 判断密码
        if (!isNotNullOrUndefined(this.patientInfo.newPassword)){
            this.http.showToast('密码为空，请输入密码！');
            return;
        }
        let bool = false;
        if (isNotNullOrUndefined(this.Date)){
            if ((new Date().getTime() - this.Date.getTime()) / 1000 > 2){
                bool = true;
            } else {
                bool = false;
            }
        } else {
            bool = true;
        }
        if (!bool){
            this.http.showToast('正在保存信息，请稍等');
            return;
        }
        this.Date = new Date();
        const cond = {
            password: this.patientInfo.newPassword,
            userId: this.patientInfo.id,
        };
        this.http.post('rcp/api/user/modifyPassword', cond, '', '', {load: true})
           .subscribe(data => {
               if (data['isSuccess']){
                 this.http.showToast('密码修改成功');
               }
           });
    }
    // 通过身份证号，获取用户信息
    getRegisterInfo(){
        this.http
            .getNotHeardPost(`rcp/register/sysuser/detail` + this.http.getParamsString({idenno: this.patientInfo.identity}), {} ,
                '通过身份证号，获取用户信息', '通过身份证号，获取用户信息失败', {load: true})
            .subscribe( data => {
                if (data['isSuccess']){
                    this.patientInfo = {
                        id: data['data']['userId'],
                        name: data['data']['userName'],
                        identity: data['data']['idenno'],
                        mobile: data['data']['mobile'],
                        verifyCode: this.patientInfo.verifyCode,
                        newPassword: undefined
                    };
                    this.step = '2';
                }
            });
    }

    // 获取验证码
    getVerifyCode(){
        this.http
            .getNotHeardBlob(`rcp/open/api/verifyCode`)
            .subscribe( data => {
               this.verifyCodeJpg = this.sanitizer.bypassSecurityTrustUrl(window.URL.createObjectURL(data.body));
               this.verifyCode = data.headers.get('verifyCode');
            });
    }
    // 校验手机号
    checkPhoneSave(){
        // 判断姓名
        if (!isNotNullOrUndefined(this.patientInfo.name) || this.patientInfo.name === '' || this.patientInfo.name.trim() === ''){
            this.http.showToast('姓名为空，请输入姓名！');
            return;
        }
        // 判断身份证号
        if (!isNotNullOrUndefined(this.patientInfo.identity)){
            this.http.showToast('请扫描身份证！');
            return;
        }
        // 判断手机号
        if (!this.checkPhone(this.patientInfo.mobile)){
            return;
        }
        // 判断验证码
        if (this.verifyCode.toUpperCase() !== this.patientInfo.verifyCode.toUpperCase()){
            this.http.showToast('验证码不正确，请重新输入！');
            return;
        }
        this.getRegisterInfo();
    }
    // 扫描身份证
    async scan() {
        this.result = (await Ocr.scan());
        if (this.http.IdentityCodeValid(this.result.num, '请重新扫描')) {
            this.dealScanResult();
        }
    }
    // 处理扫描出的信息
    dealScanResult() {
        this.patientInfo.name = this.result.name;
        this.patientInfo.identity = this.result.num;
        this.patientInfo.mobile = '';
        this.imageData = this.result.imageData;
        this.ref.detectChanges();
    }
}
